import{_ as a,H as n,f as e,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"07 | 无状态应用部署：Deployment","description":"","frontmatter":{},"headers":[{"level":2,"title":"认识 Deployment","slug":"认识-deployment","link":"#认识-deployment","children":[]},{"level":2,"title":"部署 Deployment","slug":"部署-deployment","link":"#部署-deployment","children":[{"level":3,"title":"kubectl 命令部署","slug":"kubectl-命令部署","link":"#kubectl-命令部署","children":[]},{"level":3,"title":"YAML 文件部署","slug":"yaml-文件部署","link":"#yaml-文件部署","children":[]},{"level":3,"title":"查看部署结果","slug":"查看部署结果","link":"#查看部署结果","children":[]}]},{"level":2,"title":"管理 Deployment","slug":"管理-deployment","link":"#管理-deployment","children":[]},{"level":2,"title":"Deployment 高级功能","slug":"deployment-高级功能","link":"#deployment-高级功能","children":[{"level":3,"title":"水平扩缩容","slug":"水平扩缩容","link":"#水平扩缩容","children":[]},{"level":3,"title":"滚动更新","slug":"滚动更新","link":"#滚动更新","children":[]},{"level":3,"title":"版本管理","slug":"版本管理","link":"#版本管理","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"零基础拿下云原生CKA认证/07｜无状态应用部署：Deployment.md","filePath":"零基础拿下云原生CKA认证/07｜无状态应用部署：Deployment.md","lastUpdated":1795561650000}'),p={name:"零基础拿下云原生CKA认证/07｜无状态应用部署：Deployment.md"};function l(t,s,h,o,d,k){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="_07-无状态应用部署-deployment" tabindex="-1">07 | 无状态应用部署：Deployment <a class="header-anchor" href="#_07-无状态应用部署-deployment" aria-label="Permalink to &quot;07 | 无状态应用部署：Deployment&quot;">​</a></h1><p>你好，我是雪飞。</p><p>今天开始，我们进入到 K8s 中级篇。我会带你了解部署各类应用所需要的 K8s 资源对象，掌握这些资源对象的使用，你就能够为应用设计合适的部署方案，并在 K8s 集群中完整地部署应用。</p><p>这节课我带你了解一个非常重要的资源对象——Deployment，它适用于部署无状态应用。</p><h2 id="认识-deployment" tabindex="-1">认识 Deployment <a class="header-anchor" href="#认识-deployment" aria-label="Permalink to &quot;认识 Deployment&quot;">​</a></h2><p>之前介绍过无状态应用，简单来说，这类应用不管部署在哪里都可以独立完整的运行，所以无状态应用更易于扩展和维护。网站 Web 应用就是一种常见的无状态应用，可以同时部署多个Web 应用，但是不管用户访问哪一个，得到的响应结果都一样。</p><p>Deployment 被设计用于同时部署和管理多个独立完整的 Pod，每个 Pod 里都运行相同的应用镜像，这正好对应着无状态应用的特点，所以说 Deployment 适合部署无状态应用。</p><p>Deployment 可以管理多个应用的 Pod 副本，最大的好处就是多个 Pod 一起工作，从而提高应用的处理能力。此外，即使部分 Pod 出现故障崩溃，其他 Pod 仍能继续运行，确保业务的持续可用。</p><p>举个生活中的例子，想象一下在火车站排队买票，起初只有一个售票窗口，当乘客增多时，单个售票员处理不过来，队伍就会变长，导致乘客等待时间增加。此时，如果开设多个售票窗口，乘客就会被分散到不同的窗口，加快了购票的速度。即使某个窗口的售票员临时离开，其他窗口依然可以继续服务，不会导致售票服务中断。在这个例子中，每个售票窗口就好比一个Pod，而 Deployment 则负责管理这些窗口（Pod），确保服务的高效和稳定。</p><p>下面我们来动手部署一个 Deployment。</p><h2 id="部署-deployment" tabindex="-1">部署 Deployment <a class="header-anchor" href="#部署-deployment" aria-label="Permalink to &quot;部署 Deployment&quot;">​</a></h2><p>Deployment 有两种部署方式，使用 kubectl 命令和使用 YAML 文件。</p><h3 id="kubectl-命令部署" tabindex="-1">kubectl 命令部署 <a class="header-anchor" href="#kubectl-命令部署" aria-label="Permalink to &quot;kubectl 命令部署&quot;">​</a></h3><p>可以使用 “kubectl create” 命令创建 Deployment。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​deployment名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --image=nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replicas=3</span></span></code></pre></div><ul><li><p>–image=nginx：表示 Deployment 部署的 Pod 的容器镜像是 Nginx。</p></li><li><p>–replicas=3：表示 Pod 副本数量为 3 个，即运行了 3 个 Pod，每个 Pod 的容器都使用Nginx 镜像。</p></li></ul><h3 id="yaml-文件部署" tabindex="-1">YAML 文件部署 <a class="header-anchor" href="#yaml-文件部署" aria-label="Permalink to &quot;YAML 文件部署&quot;">​</a></h3><p>上述创建 Deployment 的命令等同于以下 YAML 文件（my-nginx-dep.yaml）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># my-nginx-dep.yaml</span></span>
<span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: my-nginx-dep</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> replicas: 3 # Pod 副本预期数量</span></span>
<span class="line"><span> selector:   # 通过选择器来管理 Pod</span></span>
<span class="line"><span>   matchLabels:</span></span>
<span class="line"><span>     pod: my-nginx  # 要管理的 Pod 的标签</span></span>
<span class="line"><span> template:   # 定义 Pod 的模板</span></span>
<span class="line"><span>   metadata:</span></span>
<span class="line"><span>     labels:</span></span>
<span class="line"><span>       pod: my-nginx # Pod 的标签</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     containers:</span></span>
<span class="line"><span>     - name: nginx</span></span>
<span class="line"><span>       image: nginx</span></span></code></pre></div><ul><li><p>apiVersion：Deployment 的 apiVersion 值是 “apps/v1”。</p></li><li><p>replicas：同 “kubectl create” 命令中的参数，用来设置 Pod 副本数量。</p></li><li><p>selector：用来设置 Deployment 要管理的 Pod 的标签。Deployment 和它所管理的 Pod之间是松散耦合的关系，Deployment 通过标签选择匹配的 Pod 来管理，因此，在matchLabels 属性中指定的 “key: value” 标签必须与下面 Pod 模板 template 中的 labels 指定的 key: value 标签一致。</p></li><li><p>template：用来定义 Pod 的模板，这样 Deployment 就可以从这个模板创建出 Pod。模板里面的属性与 Pod 的 YAML 文件中的 spec 部分非常相似，不再详细介绍。需要注意的是，在 Pod 模板中，我们不需要再为 Pod 定义名称，因为部署后 Deployment 会自动为这3 个 Pod 分配名称。但是一定要记得给 Pod 添加标签 labels，而且要保证这个 labels 与Deployment 中的 matchLabels 一致。</p></li></ul><p>使用 “kubectl apply” 命令部署 Deployment 的 YAML 文件。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx-dep.yaml</span></span></code></pre></div><h3 id="查看部署结果" tabindex="-1">查看部署结果 <a class="header-anchor" href="#查看部署结果" aria-label="Permalink to &quot;查看部署结果&quot;">​</a></h3><p>执行部署命令后稍等一会，因为 Deployment 需要同时部署 3 个 Pod，这要花费一点时间。然后我们使用 “kubectl get” 命令分别查看一下 Deployment 和 Pod 的运行情况。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get deployment</span></span>
<span class="line"><span>NAME           READY   UP-TO-DATE   AVAILABLE   AGE</span></span>
<span class="line"><span>my-nginx-dep   3/3     3            3           39s</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get pod</span></span>
<span class="line"><span>NAME                            READY   STATUS    RESTARTS       AGE</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-bvzjx   1/1     Running   0              35s</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-hbg2z   1/1     Running   0              35s</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-qd7z4   1/1     Running   0              35s</span></span></code></pre></div><p>返回结果中：</p><ul><li><p>READY：表示运行的 Pod 数量，前面的数字是就绪数量，后面的数字是期望数量。</p></li><li><p>UP-TO-DATE：表示当前已经更新到最新状态的 Pod 数量。</p></li><li><p>AVAILABLE： 表示健康状态的能够正常对外提供服务的 Pod 数量。</p></li></ul><p>我们看到每个 Pod 的名称都是由 Deployment 的名称加上一个后缀组成。但是为什么后缀分为两段，第一段是相同的，而第二段则不同呢？这个问题将在稍后为你解答。</p><h2 id="管理-deployment" tabindex="-1">管理 Deployment <a class="header-anchor" href="#管理-deployment" aria-label="Permalink to &quot;管理 Deployment&quot;">​</a></h2><p>部署完 Deployment，就可以使用 kubectl 命令来管理 Deployment。在之前的课程中，我们已经使用过很多的 kubectl 命令，其实你可能已经发现很多命令是相同的，只是操作的资源对象类型或者资源对象名称不同，所以我在这里介绍一下通用的管理资源对象的命令，在后续介绍其他 K8s 资源对象时，就不再赘述这些基础的管理操作。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 查看列表</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">get</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-o wide] [-n &lt;​namespace名称&gt;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 查看详情</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl describe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n &lt;​namespace名称&gt;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 通过 YAML 文件部署</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apply</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型的YAML文件</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 删除资源对象</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n &lt;​namespace名称&gt;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型的YAML文件</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 实时编辑资源对象，进入编辑器，保存后立即生效</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl edit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象类型</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">资源对象名称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n &lt;​namespace名称&gt;]</span></span></code></pre></div><p>注意：“-n &lt;​namespace 名称 &gt; ” 表示如果资源对象属于某个命名空间，就要使用 -n 参数来指定命名空间名称，否则会提示找不到资源。</p><p>对于 Deployment ，只要将以上命令中的 &lt; 资源对象类型 &gt; 指定为 “deployment”，并将 &lt; 资源对象名称 &gt; 替换为具体部署的 Deployment 名称，就可以使用这些命令来管理Deployment。</p><h2 id="deployment-高级功能" tabindex="-1">Deployment 高级功能 <a class="header-anchor" href="#deployment-高级功能" aria-label="Permalink to &quot;Deployment 高级功能&quot;">​</a></h2><p>了解了 Deployment 的基础用法，接下来通过两个场景让我们看看 Deployment 的高级功能。</p><h3 id="水平扩缩容" tabindex="-1">水平扩缩容 <a class="header-anchor" href="#水平扩缩容" aria-label="Permalink to &quot;水平扩缩容&quot;">​</a></h3><p>你公司的应用通过 Deployment 部署了 3 个 Pod 副本，一直运行得挺稳定，刚才营销部同事说马上要搞一个优惠活动，预估会有大量访问，找你问问公司的应用能不能支撑住。这个时候，你只需要一个命令就能满足他的需求。这就需要用到 Deployment 的水平扩缩容功能。</p><p>Deployment 的水平扩缩容是指通过增加或减少 Pod 的副本数量来调整应用的并行处理能力，从而应对访问流量变化。所以当访问应用的流量大了，我们就增加 Pod 副本数量，提升并行处理能力；当访问应用的流量小了，我们就减少 Pod 副本数量，来节省资源消耗。</p><p>使用 “kubectl scale” 命令，可以方便地对 Deployment 指定新的副本数量。所以，对于营销部同事的要求，你大概估计了一下，可能需要 5 个 Pod 副本，这时，你只需要执行以下命令，就可以将 Pod 副本的数量扩充到了 5 个。（这里假设你公司的 Deployment 应用是我们上面部署的 my-nginx-dep）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl scale deployment my-nginx-dep --replicas=5</span></span>
<span class="line"><span>deployment.apps/my-nginx-dep scaled</span></span></code></pre></div><p>命令执行后，Scheduler 调度器会新调度两个同样应用的 Pod 副本。你可以通过 “kubectl get”命令查看一下结果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get deployment</span></span>
<span class="line"><span>NAME           READY   UP-TO-DATE   AVAILABLE   AGE</span></span>
<span class="line"><span>my-nginx-dep   5/5     5            5           159m</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get pod</span></span>
<span class="line"><span>NAME                            READY   STATUS    RESTARTS  AGE</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-4l4zn   1/1     Running   0         26s</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-bvzjx   1/1     Running   0         159m</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-hbg2z   1/1     Running   0         159m</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-qd7z4   1/1     Running   0         159m</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b-v8hww   1/1     Running   0         26s</span></span></code></pre></div><p>现在 K8s 集群中已经有 5 个 Pod 副本在运行应用了，同事也可以放心的开始营销活动，等活动结束你可以同样使用 “kubectl scale” 命令并且设置参数 replicas 的数量为 3，从而释放掉不需要的 Pod 副本，实现缩容功能。</p><h3 id="滚动更新" tabindex="-1">滚动更新 <a class="header-anchor" href="#滚动更新" aria-label="Permalink to &quot;滚动更新&quot;">​</a></h3><p>过了几天，研发部那边对应用做了新的功能迭代，发布了新的镜像，这个时候，就需要你对Deployment 部署的应用 Pod 副本进行更新升级，同时要求你在升级的过程中还要保持业务能正常访问。这就需要用到 Deployment 的自动化的滚动更新功能。</p><p>Deployment 的滚动更新是指在更新应用版本时，旧版本的 Pod 会逐个被新版本的 Pod 替换，直到所有 Pod 都更新完毕。这种方式确保在更新过程中，始终有能够提供服务的应用Pod，从而实现业务没有停机时间。</p><p>Deployment 具有版本概念，它与 YAML 文件中的 Pod 模板（template）内容相关，版本号实际上是 Pod 模板内容的 Hash 值。因此，当 Pod 中的镜像、配置、标签等发生变更时，都会形成新的 Deployment 版本并自动开始滚动更新。</p><p>最主要的版本升级场景是应用的镜像包更新。以下是修改 Deployment 的三种方式，只要修改了 Pod 中的应用镜像，就自动触发滚动更新过程。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通过修改 Deployment 的 YAML 文件，修改 Pod 使用的容器镜像，然后重新部署</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx-dep.yaml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通过 &quot;kubectl set&quot; 命令修改 deployment 中 Pod 的容器镜像</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/my-nginx-dep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx=nginx:1.26.0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通过 &quot;kubectl edit&quot; 命令，直接打开编辑器对 deployment 进行修改，保存立即生效</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment/my-nginx-dep</span></span></code></pre></div><p>这里介绍一下滚动更新的原理。滚动更新主要通过一个隐藏的 ReplicaSet 资源对象实现。实际上，Deployment 并不直接管理 Pod，而是通过 ReplicaSet 来管理 Pod。ReplicaSet 实际上负责管理多个副本的 Pod，每个 ReplicaSet 对应一个 Deployment 的版本。当 Deployment升级时，会同时创建一个新版本的 ReplicaSet，新版本的 ReplicaSet 开始创建新的 Pod，而旧版本的 ReplicaSet 则开始删除旧的 Pod。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/07/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/07/1.png" alt=""></a></p><p>使用 “kubectl get replicaset” 命令来查看 ReplicaSet，可以看到 Deployment 确实自动生成了一个 ReplicaSet，而且你可以看到它的名称的后缀 “5588cdb59b”，就是刚才通过 Deployment自动生成的 Pod 名称的第一段后缀（my-nginx-dep-5588cdb59b-bvzjx），这也说明了确实是“Deployment -&gt; ReplicaSet -&gt; Pod” 这个关系。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get replicaset</span></span>
<span class="line"><span>NAME                      DESIRED   CURRENT   READY   AGE</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b   3         3         3       39m</span></span></code></pre></div><p>假设你公司应用的 Deployment 是我们上面部署的 my-nginx-dep，之前业务镜像是 Nginx，默认为最新 Latest 版本，迭代功能后新发布的业务镜像是 nginx:1.26.0，你就可以通过更新镜像的命令将 Nginx 的版本更新到 1.26.0。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl set image deployment/my-nginx-dep nginx=nginx:1.26.0</span></span>
<span class="line"><span>deployment.apps/my-nginx-dep image updated</span></span></code></pre></div><p>此时，我们查看 ReplicaSet，发现已经自动创建了两个 ReplicaSet，代表着新旧两个版本，旧版本后缀是 “5588cdb59b”，新版本后缀是 “84f5b57d87”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get replicaset</span></span>
<span class="line"><span>NAME                      DESIRED   CURRENT   READY   AGE</span></span>
<span class="line"><span>my-nginx-dep-5588cdb59b   3         3         3       66m</span></span>
<span class="line"><span>my-nginx-dep-84f5b57d87   1         1         0       69s</span></span></code></pre></div><p>我们还可以使用 “kubectl rollout status” 命令来查看滚动更新过程。在这个过程中，始终保持有 Pod 去对外提供服务，从而保证了更新时的应用的连续性。然而，这也意味着新旧两个应用会同时存在一段时间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl rollout status deployment my-nginx-dep</span></span>
<span class="line"><span>Waiting for deployment &quot;my-nginx-dep&quot; rollout to finish: 2 out of 3 new replicas</span></span>
<span class="line"><span>Waiting for deployment &quot;my-nginx-dep&quot; rollout to finish: 2 out of 3 new replicas</span></span>
<span class="line"><span>Waiting for deployment &quot;my-nginx-dep&quot; rollout to finish: 2 out of 3 new replicas</span></span>
<span class="line"><span>Waiting for deployment &quot;my-nginx-dep&quot; rollout to finish: 1 old replicas are pendi</span></span>
<span class="line"><span>Waiting for deployment &quot;my-nginx-dep&quot; rollout to finish: 1 old replicas are pendi</span></span>
<span class="line"><span>deployment &quot;my-nginx-dep&quot; successfully rolled out</span></span></code></pre></div><p>最终，通过 Deployment 的自动化的滚动更新功能，你只需要执行更新 Deployment 中 Pod 镜像的命令，就实现了不中断应用的更新需求。</p><p>暂停和恢复滚动更新</p><p>在部署过程中，如果发生特殊情况，可以使用以下命令暂停和恢复 Deployment 版本更新。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 暂停更新</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pause</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​deployment名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 恢复更新</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​deployment名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h3 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h3><p>在每次升级过程中，Deployment 都会生成一个新的版本，K8s 提供了相关的命令来查看和管理这些 Deployment 的版本。</p><p>查看历史版本</p><p>使用 “kubectl rollout history” 命令可以查看历史版本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl rollout history deployment my-nginx-dep</span></span>
<span class="line"><span>deployment.apps/my-nginx-dep</span></span>
<span class="line"><span>REVISION  CHANGE-CAUSE</span></span>
<span class="line"><span>1         &lt;​none&gt;</span></span>
<span class="line"><span>2         &lt;​none&gt;</span></span></code></pre></div><p>这里发现版本 REVISION 只是数字，而且 CHANGE-CAUSE 原因也没有说明，这样的展示结果不太友好。如果我们想在每次版本升级时增加一些说明，可以通过在 Deployment 的 YAML文件的 metadata 属性中添加 annotations 属性，用来增加注解信息。YAML 文件示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: my-nginx-dep</span></span>
<span class="line"><span> annotations:</span></span>
<span class="line"><span>   kubernetes.io/change-cause: v1, 初始版本 # 可以在这里增加说明</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这样部署 Deployment 之后，就可以在历史版本中查看到版本说明信息，方便我们了解每个版本的变更原因，非常友好。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl rollout history deployment my-nginx-dep</span></span>
<span class="line"><span>deployment.apps/my-nginx-dep</span></span>
<span class="line"><span>REVISION  CHANGE-CAUSE</span></span>
<span class="line"><span>1         v1, 初始版本</span></span>
<span class="line"><span>2         v2, nginx=1.26.0</span></span></code></pre></div><p>版本回退</p><p>如果在部署过程中遇到严重问题，可以使用版本回退功能。由于 Deployment 采用 ReplicaSet进行应用部署的版本管理，因此可以方便地回退到任意历史版本。回退过程与滚动更新相似，也能持续保持服务不间断，但是版本回退事实上并不是真的回到上一版本，而是会生成一个新的 Deployment 版本。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 回滚上一个版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​deployment名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 回滚历史指定版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​deployment名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to-revision=2</span></span></code></pre></div><p>讲完了 Deployment 的高级功能，你是不是已经感受到它的强大。的确，在我们实际项目部署架构中，Deployment 是用得最多的应用部署方式，大量无状态应用（很多微服务应用也是无状态应用）都是使用 Deployment 部署到集群中。通过 Deployment 的多 Pod 副本、水平扩缩容、滚动更新等功能，保障了应用的高可用、可扩展和持续稳定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我介绍了 K8s 中的一个核心资源对象——Deployment。 Deployment 被设计用于同时部署和管理多个相同的 Pod，每个 Pod 里都运行相同的应用镜像，这些 Pod 独立运行在节点上，每个 Pod 就是应用的一个副本，所以它非常适合部署无状态应用。Deployment 部署多个Pod 的好处就是增加了业务的并发处理能力以及提供了高可用能力，确保应用更加稳定和连续。</p><p>接着我介绍了 Deployment 部署的两种方式，kubectl 命令和 YAML 文件部署，YAML 文件中的 replicas 属性用来指定 Pod 副本数量，selector 属性用来匹配要管理的 Pod 的标签，template 属性是 Pod 的内容模板。Deployment 和要管理的 Pod 是松散的关系，Deployment是通过标签来选择要管理的 Pod，所以需要注意 YAML 文件中标签的对应匹配。然后我带你动手部署了 Nginx 镜像的 Deployment，并且整理了 K8s 中的一些常用命令。</p><p>最后，我通过两个场景给你介绍了 Deployment 的水平扩缩容和滚动更新这两个高级功能。水平扩缩容是指通过增加或减少 Pod 的副本数量来调整应用的并行处理能力，从而应对访问流量变化。而滚动更新是指在更新应用版本时，旧版本的 Pod 会逐个被新版本的 Pod 替换，直到所有 Pod 都更新完毕。这些功能都保障了业务的高可用和稳定性。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这就是今天的全部内容，这节课涉及到一个扩缩容的考点，所以今天练习题如下：</p><p>请你创建一个 Nginx 镜像的 Deployment， Pod 副本数为 3，然后通过 kubectl 命令把这个Deployment 的 Pod 副本数扩容到 5 个。</p><p>相信经过动手实践，会让你对知识的理解更加深刻。</p>`,84)])])}const r=a(p,[["render",l]]);export{g as __pageData,r as default};
